import { getCustomizableElement } from "./getCustomizableElement";
import { sortDisplayElements } from "./sortDisplayElements";
import { handleElementsPriority } from "./handleElementsPriority";
import { handleShortnessOfRequiredWidth } from "./handleShortnessOfRequiredWidth";
export const getDisplayingElementsIndex = (width, children) => {
    // add customizableMore element
    const parentWithMore = Array.from(children).find(child => Array.from(child.childNodes).some(el => el.classList.contains("zen-toolbar__item--more")));
    const customizableMore = getCustomizableElement(parentWithMore);
    let displayingElements = Object.assign({}, customizableMore);
    const widthProps = {
        width,
        requiredWidth: Object.keys(customizableMore).length ? 80 : 71 // width for more button with margin or without
    };
    displayingElements = handleElementsPriority(children, widthProps, displayingElements);
    displayingElements = handleShortnessOfRequiredWidth(children, widthProps, displayingElements);
    sortDisplayElements(displayingElements);
    return { displayingElements, customizableMore };
};
